window.LIB_LAZY=window.LIB_LAZY||{};
window.LIB_LAZY["eusebiu-istoria#41"]=[{"v":1,"t":"Astfel era starea iudeilor. Între timp, sfinții apostoli și ucenici ai Mântuitorului nostru erau risipiți prin lume. Partia, după tradiție, a fost dată lui Toma ca ogor de lucru, Sciția lui Andrei, iar Asia lui Ioan, care, după ce a trăit un timp acolo, a murit la Efes."},{"v":2,"t":"Petru pare să fi predicat în Pont, Galatia, Bitinia, Capadocia și Asia, iudeilor din împrăștiere. Și la urmă, venind la Roma, a fost răstignit cu capul în jos; căci ceruse să sufere în acest chip. Ce avem nevoie să spunem despre Pavel, care a predicat Evanghelia lui Hristos de la Ierusalim până în Iliric și a suferit după aceea martiriul la Roma sub Nero? Aceste fapte sunt povestite de Origen în volumul al treilea al Comentariului său la Geneza."}];
window.LIB_LAZY["eusebiu-istoria#42"]=[{"v":1,"t":"După martiriul lui Pavel și al lui Petru, Lin a fost cel dintâi care a căpătat episcopatul Bisericii din Roma. Pavel îl pomenește, când scrie lui Timotei de la Roma, în salutul de la sfârșitul epistolei."}];
window.LIB_LAZY["eusebiu-istoria#43"]=[{"v":1,"t":"O epistolă a lui Petru, cea numită întâi, este recunoscută ca autentică. Și pe aceasta bătrânii din vechime o foloseau în voie în propriile lor scrieri ca pe o lucrare necontestată. Dar am aflat că a doua epistolă a lui, care există, nu aparține canonului; totuși, pentru că s-a arătat folositoare multora, a fost folosită împreună cu celelalte Scripturi."},{"v":2,"t":"Așa-numitele Fapte ale lui Petru, însă, și Evanghelia care poartă numele lui, și Predica și Apocalipsa, cum se numesc, știm că nu au fost primite de toți, pentru că niciun scriitor bisericesc, din vechime sau din vremea noastră, nu s-a slujit de mărturii luate din ele."},{"v":3,"t":"Dar în cursul istoriei mele voi avea grijă să arăt, pe lângă succesiunea oficială, ce scriitori bisericești s-au slujit din când în când de vreuna dintre lucrările disputate și ce au spus despre scrierile canonice și primite, precum și despre cele care nu sunt din această categorie."},{"v":4,"t":"Astfel sunt scrierile care poartă numele lui Petru, dintre care numai una știu că este autentică și recunoscută de bătrânii din vechime."},{"v":5,"t":"Cele paisprezece epistole ale lui Pavel sunt bine cunoscute și necontestate. Nu este, într-adevăr, drept să trecem cu vederea faptul că unii au respins Epistola către Evrei, spunând că este contestată de biserica Romei, pe motiv că nu a fost scrisă de Pavel. Dar ce s-a spus despre această epistolă de cei care au trăit înaintea vremii noastre voi cita la locul potrivit. În privința așa-numitelor Fapte ale lui Pavel, nu le-am găsit printre scrierile necontestate."},{"v":6,"t":"Dar de vreme ce același apostol, în salutările de la sfârșitul Epistolei către Romani, a pomenit, printre alții, pe Herma, căruia i se atribuie cartea numită Păstorul, trebuie observat că și aceasta a fost contestată de unii și din pricina lor nu poate fi așezată printre cărțile recunoscute; în timp ce de alții este socotită cu totul indispensabilă, mai ales pentru cei care au nevoie de învățătură în elementele credinței. De aceea, după cum știm, a fost citită public în biserici și am găsit că unii dintre cei mai vechi scriitori s-au slujit de ea."},{"v":7,"t":"Aceasta va ajunge ca să arate scrierile dumnezeiești care sunt necontestate, precum și cele care nu sunt recunoscute de toți."}];
window.LIB_LAZY["eusebiu-istoria#44"]=[{"v":1,"t":"Că Pavel a predicat neamurilor și a pus temeliile bisericilor „de la Ierusalim și în jur până în Iliric” este vădit și din propriile lui cuvinte (Romani 15:19), și din povestirea pe care a dat-o Luca în Fapte."},{"v":2,"t":"Și în câte provincii a predicat Petru pe Hristos și a învățat doctrina noului legământ celor din tăierea împrejur este limpede din propriile lui cuvinte în epistola lui pomenită deja ca necontestată, în care scrie evreilor din împrăștiere din Pont, Galatia, Capadocia, Asia și Bitinia. (1 Petru 1:1)"},{"v":3,"t":"Dar numărul și numele celor dintre ei care au devenit urmași adevărați și râvnitori ai apostolilor și au fost socotiți vrednici să păstorească bisericile întemeiate de ei nu este ușor de spus, afară de cei pomeniți în scrierile lui Pavel."},{"v":4,"t":"Căci avea nenumărați împreună-lucrători, sau „tovarăși de arme”, cum îi numea, și cei mai mulți dintre ei au fost cinstiți de el cu o pomenire nepieritoare, căci a dat mărturie statornică despre ei în propriile lui epistole."},{"v":5,"t":"Și Luca, în Fapte, vorbește despre prietenii lui și îi pomenește pe nume."},{"v":6,"t":"Timotei, după cum se însemnează, a fost cel dintâi care a primit episcopatul parohiei din Efes, iar Tit al bisericilor din Creta."},{"v":7,"t":"Dar Luca, care era de neam antiohian și doctor de meserie și care a fost deosebit de apropiat de Pavel și bine cunoscut cu ceilalți apostoli, ne-a lăsat, în două cărți insuflate, dovezi ale acelei arte duhovnicești de vindecare pe care a învățat-o de la ei. Una dintre aceste cărți este Evanghelia, pe care mărturisește că a scris-o după cum i-au dat-o cei care de la început au fost martori oculari și slujitori ai cuvântului, pe toți urmându-i, cum spune, cu exactitate de la început. (Luca 1:2-3) Cealaltă carte este Faptele Apostolilor, pe care a alcătuit-o nu din povestirile altora, ci din ce văzuse el însuși."},{"v":8,"t":"Și se spune că Pavel a avut în vedere Evanghelia lui Luca oriunde, ca și cum ar vorbi de o evanghelie a lui, a folosit cuvintele „după Evanghelia mea”."},{"v":9,"t":"În privința restului urmașilor lui, Pavel mărturisește că Crescent a fost trimis în Galia; iar Lin, pe care îl pomenește în a doua epistolă către Timotei (2 Timotei 4:21) ca tovarăș al lui la Roma, a fost urmașul lui Petru în episcopatul bisericii de acolo, după cum s-a arătat deja."},{"v":10,"t":"Clement, de asemenea, care a fost rânduit al treilea episcop al bisericii din Roma, a fost, după cum mărturisește Pavel, împreună-lucrătorul și tovarășul lui de arme."},{"v":11,"t":"Pe lângă aceștia, acel areopagit, numit Dionisie, care a fost cel dintâi care a crezut după cuvântarea lui Pavel către atenieni în Areopag (după cum însemnează Luca în Fapte), este pomenit de un alt Dionisie, scriitor din vechime și păstor al parohiei din Corint, ca primul episcop al bisericii din Atena."},{"v":12,"t":"Dar întâmplările legate de succesiunea apostolică le vom povesti la vremea potrivită. Între timp să continuăm cursul istoriei noastre."}];
window.LIB_LAZY["eusebiu-istoria#45"]=[{"v":1,"t":"După ce Nero ținuse puterea treisprezece ani și Galba și Otho domniseră un an și șase luni, Vespasian, care se făcuse vestit în campaniile împotriva iudeilor, a fost proclamat suveran în Iudeea și a primit titlul de împărat de la oștirile de acolo. Pornind îndată, deci, spre Roma, a încredințat conducerea războiului împotriva iudeilor fiului său Tit."},{"v":2,"t":"Căci iudeii, după înălțarea Mântuitorului nostru, pe lângă crima lor împotriva Lui, născociseră câte uneltiri au putut împotriva apostolilor Lui. Întâi Ștefan a fost omorât de ei cu pietre și după el Iacov, fiul lui Zevedeu și fratele lui Ioan, a fost decapitat și, în sfârșit, Iacov, cel dintâi care căpătase scaunul de episcop din Ierusalim după înălțarea Mântuitorului nostru, a murit în chipul deja descris. Dar ceilalți apostoli, împotriva cărora s-au uneltit necontenit în vederea nimicirii lor și care fuseseră izgoniți din țara Iudeii, au mers la toate neamurile să predice Evanghelia, bizuindu-se pe puterea lui Hristos, care le spusese: «Duceți-vă și faceți ucenici din toate neamurile în numele Meu.»"},{"v":3,"t":"Dar poporul bisericii din Ierusalim primise poruncă printr-o descoperire dată acolo unor oameni încercați, înainte de război, să părăsească cetatea și să locuiască într-un anume oraș al Pereii numit Pella. Și când cei care credeau în Hristos au venit acolo de la Ierusalim, atunci, ca și cum cetatea împărătească a iudeilor și toată țara Iudeii ar fi fost cu totul lipsite de oameni sfinți, judecata lui Dumnezeu i-a ajuns în sfârșit pe cei care săvârșiseră asemenea ocări împotriva lui Hristos și a apostolilor Lui și a nimicit cu totul acea generație de oameni nelegiuiți."},{"v":4,"t":"Dar numărul nenorocirilor care au căzut pretutindeni peste neam în acel timp; nenorocirile extreme la care au fost supuși în chip deosebit locuitorii Iudeii, miile de oameni, precum și femei și copii, care au pierit prin sabie, prin foamete și prin alte feluri de moarte nenumărate — toate aceste lucruri, precum și multele mari asedii care s-au dus împotriva cetăților Iudeii și suferințele nemăsurate îndurate de cei care au fugit la Ierusalimul însuși, ca la o cetate de deplină siguranță, și, în sfârșit, mersul general al întregului război, precum și întâmplările lui deosebite în amănunt, și cum, la urmă, urâciunea pustiirii, vestită de proroci (Daniel 9:27), a stat chiar în templul lui Dumnezeu, atât de vestit din vechime, templul care aștepta acum nimicirea lui totală și de pe urmă prin foc — toate aceste lucruri le poate găsi oricine dorește descrise cu exactitate în istoria scrisă de Josephus."},{"v":5,"t":"Dar este necesar să spunem că acest scriitor însemnează că mulțimea celor adunați din toată Iudeea la vremea Paștilor, în număr de trei milioane de suflete, au fost închiși în Ierusalim „ca într-o temniță”, ca să folosim propriile lui cuvinte."},{"v":6,"t":"Căci era drept ca tocmai în zilele în care îi pricinuiseră suferință Mântuitorului și Binefăcătorului tuturor, Hristosul lui Dumnezeu, în acele zile, închiși „ca într-o temniță”, să întâmpine nimicirea din mâinile dreptății dumnezeiești."},{"v":7,"t":"Dar trecând peste nenorocirile deosebite pe care le-au pătimit din încercările făcute împotriva lor cu sabia și cu alte mijloace, socotesc necesar să povestesc numai nenorocirile pe care le-a pricinuit foametea, ca cei care citesc această lucrare să aibă vreun mijloc de a ști că Dumnezeu nu a zăbovit să facă răzbunare asupra lor pentru răutatea lor împotriva Hristosului lui Dumnezeu."}];
window.LIB_LAZY["eusebiu-istoria#46"]=[{"v":1,"t":"Luând din nou în mâini cartea a cincea a Istoriei lui Josephus, să trecem prin tragedia întâmplărilor care au avut loc atunci."},{"v":2,"t":"„Pentru cei bogați”, spune el, era la fel de primejdios să rămână. Căci sub pretextul că aveau de gând să dezerteze, oamenii erau dați la moarte pentru averea lor. Nebunia răzvrătirilor creștea odată cu foametea și ambele nenorociri se aprindeau tot mai mult de la o zi la alta."},{"v":3,"t":"Nicăieri nu se vedea hrană; ci, spărgând casele, oamenii le scotoceau cu desăvârșire și, ori de câte ori găseau ceva de mâncare, își chinuiau stăpânii pe motiv că tăgăduiseră că ar avea ceva; dar dacă nu găseau nimic, îi chinuiau pe motiv că ascunseseră mai cu grijă."},{"v":4,"t":"Dovada că au sau nu hrană se găsea în trupurile nenorociților. Pe cei dintre ei care erau încă în stare bună îi socoteau bine aprovizionați cu hrană, iar pe cei deja slăbiți îi lăsau în pace, căci părea absurd să omoare pe cei care erau pe cale să piară de lipsă."},{"v":5,"t":"Mulți, într-adevăr, își vindeau pe ascuns averile pe o măsură de grâu, dacă erau din clasa mai bogată, sau de orz, dacă erau mai săraci. Apoi, închizându-se în cele mai dinăuntru părți ale caselor lor, unii mâncau grâul necopt din pricina cumplitei lor lipse, iar alții îl coceau după cum îi îndemnau nevoia și frica."},{"v":6,"t":"Nicăieri nu se puneau mese, ci, smulgând din foc hrana încă necoaptă, o sfâșiau în bucăți. Jalnică era hrana și o priveliște de plâns era să vezi pe cei mai puternici asigurându-și belșug, în timp ce cei mai slabi se tânguiau."},{"v":7,"t":"Dintre toate relele, într-adevăr, foametea este cea mai rea și nu nimicește nimic atât de eficient ca sfiala. Căci ceea ce în alte împrejurări este vrednic de respect este în mijlocul foametei disprețuit. Astfel femeile smulgeau hrana chiar din gura bărbaților și a copiilor lor, din a taților, și, ceea ce era mai vrednic de milă dintre toate, mamele din a pruncilor lor. Și pe când cei mai dragi ai lor se topeau în brațele lor, nu li se făcea rușine să le ia ultimele picături care le susțineau viața."},{"v":8,"t":"Și chiar în timp ce mâncau astfel, nu rămâneau nedescoperiți. Ci pretutindeni se arătau răzvrătiții, ca să-i jefuiască chiar și de aceste părți de hrană. Căci ori de câte ori vedeau o casă încuiată, o socoteau semn că cei dinăuntru iau hrană. Și spărgând îndată ușile, se năpusteau înăuntru și puneau mâna pe ce mâncau, aproape scoțându-le cu forța chiar din gâtlejul lor."},{"v":9,"t":"Bătrânii care se țineau strâns de hrana lor erau bătuți și, dacă femeile o ascundeau în mâini, li se smulgeau părul pentru aceasta. Nu era milă nici pentru păr cărunt, nici pentru prunci, ci, luând pruncii care se agățau de bucățile lor de hrană, îi izbeau de pământ. Dar față de cei care le prevenise intrarea și înghițiseră ce erau ei pe cale să ia, erau și mai cruzi, întocmai ca și cum ar fi fost nedreptățiți de ei."},{"v":10,"t":"Și născoceau cele mai cumplite chipuri de chin ca să descopere hrană, astupând căile ascunse ale nenorociților cu ierburi amare și străpungându-le șezutul cu vergi ascuțite. Și oamenii îndurau lucruri cumplite chiar de auzit, ca să fie siliți să mărturisească că au o pâine sau ca să fie făcuți să dea pe față o singură drahmă de orz pe care o ascunseseră. Dar chinuitorii înșiși nu suferau de foame."},{"v":11,"t":"Purtarea lor ar fi putut părea, într-adevăr, mai puțin barbară dacă ar fi fost mânați la ea de nevoie; dar o făceau pentru a-și exercita nebunia și pentru a-și asigura hrana pentru zilele următoare."},{"v":12,"t":"Și când vreunul se strecura din cetate noaptea până la avanposturile romanilor ca să adune ierburi sălbatice și iarbă, ei îi ieșeau în întâmpinare; și când credea că scăpase deja de dușman, îi luau ce adusese cu el și, chiar dacă adesea omul îi ruga și, chemând numele cel mai înfricoșător al lui Dumnezeu, îi conjura să-i dea o parte din ce căpătase cu primejdia vieții, nu-i dădeau nimic înapoi. Era, într-adevăr, un noroc dacă cel jefuit nu era și omorât."},{"v":13,"t":"La această povestire Josephus, după ce istorisește alte lucruri, adaugă următoarele: Fiind pusă capăt posibilității de a ieși din cetate, toată nădejdea de scăpare a iudeilor a fost tăiată. Și foametea a crescut și a mistuit poporul pe case și pe familii. Și încăperile erau pline de femei și copii morți, ulițele cetății de leșurile bătrânilor."},{"v":14,"t":"Copii și tineri, umflați de foamete, umblau prin piețe ca niște umbre și cădeau oriunde îi apuca agonia morții. Bolnavii nu aveau destulă putere ca să-și îngroape nici măcar propriile rude, iar cei care aveau puterea șovăiau din pricina mulțimii morților și a nesiguranței în privința propriei lor soarte. Mulți, într-adevăr, au murit pe când îngropau pe alții și mulți s-au dus la mormintele lor înainte de a veni moartea peste ei."},{"v":15,"t":"Nu era nici plâns, nici tânguire în aceste nenorociri; ci foametea înăbușea simțirile firești. Cei care mureau o moarte lentă priveau cu ochi uscați la cei care se duseseră la odihnă înaintea lor. O tăcere adâncă și o noapte încărcată de moarte înconjura cetatea."},{"v":16,"t":"Dar tâlharii erau mai cumpliți decât aceste nenorociri; căci spărgeau casele, care erau acum simple morminte, jefuiau morții și luau acoperământul de pe trupurile lor și plecau râzând. Încercau vârfurile săbiilor în trupurile moarte și pe unii care zăceau încă vii pe pământ îi străpungeau ca să-și încerce armele. Dar pe cei care se rugau să-și slujească de dreapta și sabia lor împotriva lor, îi lăsau cu dispreț să fie nimiciți de foamete. Fiecare dintre aceștia murea cu ochii ațintiți spre templu; și îi lăsau pe răzvrătiți în viață."},{"v":17,"t":"Aceștia au dat la început poruncă să fie îngropați morții din vistieria publică, căci nu puteau îndura duhoarea. Dar după aceea, când nu au mai putut face aceasta, au aruncat trupurile de pe ziduri în șanțuri."},{"v":18,"t":"Și când Tit a făcut ocolul și a văzut șanțurile pline de morți și sângele des care se scurgea din trupurile putrede, a scos un geamăt și, ridicându-și mâinile, a chemat pe Dumnezeu ca martor că aceasta nu era fapta lui."},{"v":19,"t":"După ce vorbește despre alte câteva lucruri, Josephus merge mai departe astfel: „Nu pot șovăi să declar ceea ce simțămintele mă silesc. Socotesc că, dacă romanii ar fi zăbovit mai mult să vină împotriva acestor nenorociți vinovați, cetatea ar fi fost înghițită de o prăpastie sau acoperită de un potop sau lovită de asemenea trăsnete cu care a fost nimicită Sodoma. Căci născuse o generație de oameni mult mai fără Dumnezeu decât cei care au suferit asemenea pedeapsă. Prin nebunia lor, într-adevăr, a fost adus tot poporul la nimicire.”"},{"v":20,"t":"Și în cartea a șasea scrie astfel: Dintre cei care au pierit de foamete în cetate, numărul a fost fără număr și nenorocirile pe care le-au îndurat de nespus. Căci dacă se arăta în vreo casă măcar umbra hranei, era război, și cei mai dragi prieteni se luptau corp la corp unii cu alții și își smulgeau unii altora cele mai nenorocite sprijine ale vieții."},{"v":21,"t":"Nici nu credeau că chiar cei care mureau erau fără hrană; ci tâlharii îi scotoceau pe când își dădeau duhul, ca nu cumva cineva să se prefacă mort, ascunzând hrană la sân. Cu gura căscată de lipsa hranei, se poticneau și se clătinau ca niște câini turbați și băteau în uși ca niște beți și, în neputința lor, se năpusteau în aceleași case de două sau trei ori într-un singur ceas."},{"v":22,"t":"Nevoia îi silea să mănânce orice puteau găsi și adunau și devorau lucruri care nu erau potrivite nici măcar pentru cele mai murdare dintre dobitoacele necuvântătoare. În sfârșit nu s-au ferit nici de curele și încălțăminte și dezlipeau pielea de pe scuturile lor și o devorau. Unii se slujeau chiar de mănunchiuri de fân vechi ca hrană, iar alții adunau cioate și vindeau cea mai mică greutate din ele cu patru drahme atice."},{"v":23,"t":"Dar de ce să vorbesc despre neobrăzarea care s-a arătat în timpul foametei față de lucruri nesimțitoare? Căci sunt pe cale să povestesc un fapt cum nu este însemnat nici de greci, nici de barbari; cumplit de povestit, de necrezut de auzit. Și, într-adevăr, aș fi omis cu plăcere această nenorocire, ca să nu par urmașilor povestitor de istorii născocite, dacă nu aș avea nenumărați martori ai ei în propria mea epocă. Și, pe lângă aceasta, aș aduce țării mele un slab serviciu dacă aș trece sub tăcere povestirea suferințelor pe care le-a îndurat."},{"v":24,"t":"Era o anumită femeie numită Maria care locuia dincolo de Iordan, al cărei tată era Eleazar, din satul Betezor (care înseamnă casa isopului). Era vestită prin neamul și averea ei și fugise cu restul mulțimii la Ierusalim și era închisă acolo cu ei în timpul asediului."},{"v":25,"t":"Tiranii o jefuiseră de restul averii pe care o adusese cu ea în cetate din Perea. Și rămășițele posesiunilor ei și orice hrană se vedea, paznicii se năpusteau zilnic și i le smulgeau. Aceasta a făcut pe femeie cumplit de mânioasă și prin ocările și blestemele ei dese a stârnit mânia ticăloșilor lacomi împotriva ei."},{"v":26,"t":"Dar nimeni, nici din mânie, nici din milă, nu voia să o omoare; și ea s-a săturat să găsească hrană pentru ca alții să mănânce. Căutarea era și ea deja pretutindeni grea, și foametea îi străpungea măruntaiele și măduva, iar resentimentul se înfuria mai violent decât foametea. Luând, deci, mânia și nevoia drept sfătuitori, a trecut să facă un lucru cu totul împotriva firii."},{"v":27,"t":"Apucându-și copilul, un băiat care sugea la sânul ei, a zis: O, nenorocit copil, în război, în foamete, în răzvrătire, pentru ce te păstrez? Robi între romani vom fi chiar dacă ne vor lăsa să trăim. Dar chiar robia este prevenită de foamete, iar răzvrătiții sunt mai cruzi decât amândouă. Haide, fii hrană pentru mine, o furie pentru acești răzvrătiți și o pildă de ocară pentru lume, căci aceasta este tot ce mai lipsește ca să desăvârșească nenorocirile iudeilor."},{"v":28,"t":"Și când a spus aceasta, și-a omorât fiul; și, după ce l-a fript, a mâncat jumătate ea însăși și, acoperind restul, l-a păstrat. Foarte curând răzvrătiții s-au arătat la fața locului și, simțind mirosul nelegiuit, au amenințat că o vor omorî îndată dacă nu le arată ce pregătise. Ea a răspuns că păstrase o parte excelentă pentru ei și cu aceasta a descoperit rămășițele copilului."},{"v":29,"t":"Au fost cuprinși îndată de groază și uimire și au rămas țintuiți la vedere. Dar ea a zis: Acesta este propriul meu fiu și fapta este a mea. Mâncați, căci am mâncat și eu. Nu fiți mai miloși decât o femeie, nici mai plini de milă decât o mamă. Dar dacă sunteți prea evlavioși și vă dați înapoi de la jertfa mea, eu am mâncat deja din ea; să rămână și restul pentru mine."},{"v":30,"t":"La aceste cuvinte oamenii au ieșit tremurând, speriați, în acest singur caz; totuși cu greu au lăsat acea hrană mamei. Îndată toată cetatea s-a umplut de cumplita faptă și, pe măsură ce fiecare își punea înaintea ochilor fapta înfricoșătoare, tremura ca și cum ar fi făcut-o el însuși."},{"v":31,"t":"Cei care sufereau de foamete doreau acum moartea; și fericiți erau cei care muriseră înainte de a auzi și a vedea asemenea nenorociri."},{"v":32,"t":"Aceasta a fost răsplata pe care au primit-o iudeii pentru răutatea și nelegiuirea lor împotriva Hristosului lui Dumnezeu."}];
window.LIB_LAZY["eusebiu-istoria#47"]=[{"v":1,"t":"Se cuvine să adăugăm la aceste povestiri adevărata prezicere a Mântuitorului nostru în care a vestit mai dinainte chiar aceste întâmplări."},{"v":2,"t":"Cuvintele Lui sunt următoarele: „Vai de cele însărcinate și de cele care alăptează în acele zile! Dar rugați-vă ca fuga voastră să nu fie iarna, nici în ziua Sabatului. Căci va fi mare necaz, cum nu a mai fost de la începutul lumii până acum, nici nu va mai fi.”"},{"v":3,"t":"Istoricul, socotind numărul total al celor omorâți, spune că au pierit un milion o sută de mii de persoane prin foamete și sabie și că restul răzvrătiților și tâlharilor, fiind trădați unii de alții după luarea cetății, au fost omorâți. Dar cei mai înalți dintre tineri și cei care se deosebeau prin frumusețe au fost păstrați pentru triumf. Dintre restul mulțimii, cei care aveau peste șaptesprezece ani au fost trimiși ca prizonieri la muncă în lucrările din Egipt, iar și mai mulți au fost risipiți prin provincii ca să-și întâmpine moartea în teatre, prin sabie și fiare. Cei care aveau sub șaptesprezece ani au fost duși ca să fie vânduți ca robi și numai dintre aceștia numărul a ajuns la nouăzeci de mii."},{"v":4,"t":"Aceste lucruri s-au petrecut astfel în al doilea an al domniei lui Vespasian, potrivit proorociilor Domnului și Mântuitorului nostru Isus Hristos, Care, prin putere dumnezeiască, le-a văzut mai dinainte ca și cum ar fi fost deja de față și a plâns și S-a tânguit, după povestirea sfinților evangheliști, care dau chiar cuvintele pe care le-a rostit când, ca și cum S-ar fi adresat Ierusalimului însuși, a zis:"},{"v":5,"t":"„De ai fi cunoscut și tu, măcar în această zi, cele ce sunt spre pacea ta! Dar acum ele sunt ascunse de ochii tăi. Căci vor veni zile peste tine, când vrăjmașii tăi vor ridica un val împrejurul tău și te vor înconjura și te vor strânge din toate părțile și te vor doborî la pământ pe tine și pe copiii tăi.”"},{"v":6,"t":"Și apoi, ca și cum ar vorbi despre popor, spune: „Căci va fi mare strâmtorare în țară și mânie peste acest popor. Și vor cădea de ascuțișul sabiei și vor fi duși robi în toate neamurile. Și Ierusalimul va fi călcat în picioare de neamuri, până se vor împlini vremurile neamurilor.” Și iarăși: „Când veți vedea Ierusalimul înconjurat de oștiri, să știți atunci că pustiirea lui este aproape.”"},{"v":7,"t":"Dacă cineva pune alături cuvintele Mântuitorului nostru cu celelalte povestiri ale istoricului despre întregul război, cum poate să nu se mire și să recunoască că prevederea și proorocia Mântuitorului nostru au fost cu adevărat dumnezeiești și minunat de ciudate."},{"v":8,"t":"Despre acele nenorociri, deci, care au căzut peste tot neamul iudeilor după patima Mântuitorului și după cuvintele pe care le-a rostit mulțimea iudeilor, când au cerut eliberarea tâlharului și ucigașului, dar au rugat ca Domnitorul Vieții să fie luat din mijlocul lor, nu este necesar să adăugăm nimic la povestirea istoricului."},{"v":9,"t":"Dar poate fi cuvenit să pomenim și acele întâmplări care au arătat bunătatea acelei Purtări de grijă prea bune care a oprit nimicirea lor patruzeci de ani întregi după crima lor împotriva lui Hristos — în care timp mulți dintre apostoli și ucenici, și însuși Iacov, primul episcop de acolo, cel care este numit fratele Domnului, erau încă în viață și locuiau chiar în Ierusalim și au rămas cea mai sigură întăritură a locului. Purtarea de grijă dumnezeiască S-a arătat astfel încă îndelung răbdătoare față de ei, ca să vadă dacă prin pocăință pentru ce făcuseră ar putea căpăta iertare și mântuire; și pe lângă o asemenea îndelungă răbdare, Purtarea de grijă a dat și semne minunate ale celor ce aveau să li se întâmple dacă nu se vor pocăi."},{"v":10,"t":"De vreme ce aceste lucruri au fost socotite vrednice de pomenire de istoricul deja citat, nu putem face mai bine decât să le povestim spre folosul cititorilor acestei lucrări."}];
window.LIB_LAZY["eusebiu-istoria#48"]=[{"v":1,"t":"Luând, deci, lucrarea acestui autor, citește ce însemnează în cartea a șasea a Istoriei lui. Cuvintele lui sunt următoarele: Astfel a fost câștigat în acest timp nenorocitul popor de înșelători și de proorocii mincinoși; dar nu au luat seama și nu au dat crezare vedeniilor și semnelor care vesteau pustiirea apropiată. Dimpotrivă, ca loviți de trăsnet și ca și cum nu ar fi avut nici ochi, nici minte, au disprețuit vestirile lui Dumnezeu."},{"v":2,"t":"Odată a stat deasupra cetății o stea în formă de sabie și o cometă care a ținut un an întreg; și iarăși, înainte de răzvrătire și înainte de tulburările care au dus la război, când poporul era adunat pentru sărbătoarea azimelor, în ziua a opta a lunii Xanticos, la ceasul al nouălea al nopții, o lumină atât de mare a strălucit în jurul altarului și al templului încât părea zi luminoasă; și aceasta a ținut o jumătate de oră. Aceasta s-a părut celor neîncercați un semn bun, dar a fost tâlcuită de cărturarii sfinți ca prevestind acele întâmplări care au avut loc foarte curând."},{"v":3,"t":"Și la aceeași sărbătoare o vacă, dusă de marele preot să fie jertfită, a născut un miel în mijlocul templului."},{"v":4,"t":"Și poarta de răsărit a templului dinăuntru, care era de bronz și foarte masivă și care seara era închisă cu greu de douăzeci de oameni și se sprijinea pe grinzi legate cu fier și avea zăvoare înfipte adânc în pământ, a fost văzută la ceasul al șaselea al nopții deschizându-se de la sine."},{"v":5,"t":"Și nu multe zile după sărbătoare, în ziua a douăzeci și una a lunii Artemisios, s-a văzut o anume vedenie minunată care întrece orice crezare. Minunea ar putea părea născocită dacă nu ar fi povestită de cei care au văzut-o și dacă nenorocirile care au urmat nu ar fi vrednice de asemenea semne. Căci înainte de apusul soarelui s-au văzut care și cete înarmate prin toată regiunea în văzduh, învârtindu-se prin nori și înconjurând cetățile."},{"v":6,"t":"Și la sărbătoarea care se numește Cincizecime, când preoții au intrat noaptea în templu, după obiceiul lor, ca să săvârșească slujbele, au spus că la început au simțit o mișcare și un zgomot și după aceea un glas ca al unei mari mulțimi, care spunea: «Să plecăm de aici.»"},{"v":7,"t":"Dar ce urmează este și mai cumplit; căci un anume Isus, fiul lui Anania, un om de rând de la țară, cu patru ani înainte de război, când cetatea era deosebit de prosperă și pașnică, a venit la sărbătoare, la care obiceiul era ca toți să-și facă colibe la templu spre cinstea lui Dumnezeu, și deodată a început să strige: «Un glas dinspre răsărit, un glas dinspre apus, un glas dinspre cele patru vânturi, un glas împotriva Ierusalimului și a templului, un glas împotriva mirilor și a miresilor, un glas împotriva întregului popor.» Zi și noapte umbla prin toate ulițele strigând astfel."},{"v":8,"t":"Dar unii dintre cetățenii mai de seamă, mâniați de strigătul de rău augur, au prins pe om și l-au bătut cu multe lovituri. Dar fără să rostească un cuvânt în apărarea lui sau să spună ceva deosebit celor de față, a continuat să strige aceleași cuvinte ca mai înainte."},{"v":9,"t":"Și cârmuitorii, socotind, cum era adevărat, că omul era mișcat de o putere mai înaltă, l-au adus înaintea guvernatorului roman. Și atunci, deși a fost biciuit până la os, nu a făcut nicio rugăminte și nu a vărsat lacrimi, ci, schimbându-și glasul la tonul cel mai jalnic cu putință, a răspuns la fiecare lovitură cu cuvintele: «Vai, vai de Ierusalim.»"},{"v":10,"t":"Același istoric însemnează un alt fapt și mai minunat decât acesta. Spune că s-a găsit în scrierile lor sfinte o anume proorocie care declara că în acel timp un anume om va ieși din țara lor ca să stăpânească lumea. El însuși a înțeles că aceasta s-a împlinit în Vespasian."},{"v":11,"t":"Dar Vespasian nu a stăpânit toată lumea, ci numai acea parte a ei care era supusă romanilor. Cu mai bun temei se poate aplica lui Hristos; căruia i-a spus Tatăl: „Cere-Mi și îți voi da neamurile ca moștenire și marginile pământului ca stăpânire.” În chiar acel timp, într-adevăr, glasul sfinților Lui apostoli „a ieșit prin tot pământul și cuvintele lor până la marginile lumii”."}];
window.LIB_LAZY["eusebiu-istoria#49"]=[{"v":1,"t":"După toate acestea se cuvine să știm câte ceva despre obârșia și familia lui Josephus, care a contribuit atât de mult la istoria de față. El însuși ne dă înștiințare despre acest punct în cuvintele următoare: „Josephus, fiul lui Matatia, preot din Ierusalim, care el însuși a luptat la început împotriva romanilor și a fost silit să fie de față la ce s-a întâmplat după aceea.”"},{"v":2,"t":"Era cel mai vestit dintre toți iudeii din acea vreme, nu numai între ai lui, ci și între romani, așa încât a fost cinstit cu ridicarea unei statui la Roma, iar lucrările lui au fost socotite vrednice de un loc în bibliotecă."},{"v":3,"t":"A scris toate Antichitățile iudeilor în douăzeci de cărți și o istorie a războiului cu romanii care a avut loc în vremea lui, în șapte cărți. El însuși mărturisește că această din urmă lucrare nu a fost scrisă numai în greacă, ci a fost tradusă și de el însuși în limba lui maternă. Este vrednic de crezare aici din pricina sincerității lui în alte privințe."},{"v":4,"t":"Mai există și alte două cărți ale lui, care merită citite. Ele tratează despre vechimea iudeilor și în ele îi răspunde lui Apion Gramaticul, care scrisese în acel timp un tratat împotriva iudeilor, și altora care încercaseră să defaime așezămintele moștenite ale poporului iudeu."},{"v":5,"t":"În prima dintre aceste cărți dă numărul cărților canonice ale așa-numitului Vechi Testament. Luându-și, se pare, înștiințarea din tradiția veche, arată ce cărți erau primite fără dispută între evrei. Cuvintele lui sunt următoarele."}];
window.LIB_LAZY["eusebiu-istoria#50"]=[{"v":1,"t":"Nu avem, deci, o mulțime de cărți care să se contrazică și să se combată între ele; ci avem numai douăzeci și două, care cuprind însemnarea întregii vremi și sunt socotite pe drept dumnezeiești."},{"v":2,"t":"Dintre acestea, cinci sunt ale lui Moise și cuprind legile și tradiția despre obârșia omului și continuă istoria până la moartea lui. Această perioadă cuprinde aproape trei mii de ani."},{"v":3,"t":"De la moartea lui Moise până la moartea lui Artaxerxe, care i-a urmat lui Xerxe ca rege al Persiei, proorocii care i-au urmat lui Moise au scris istoria vremurilor lor în treisprezece cărți. Celelalte patru cărți cuprind imnuri către Dumnezeu și porunci pentru rânduirea vieții oamenilor."},{"v":4,"t":"De la vremea lui Artaxerxe până în ziua noastră, toate întâmplările au fost însemnate, dar povestirile nu sunt vrednice de aceeași încredere pe care o avem în cele dinaintea lor, pentru că nu a existat în acest timp o succesiune exactă de proroci."},{"v":5,"t":"Cât de mult suntem legați de propriile noastre scrieri se vede limpede din purtarea noastră față de ele. Căci deși a trecut deja o perioadă atât de mare, nimeni nu a cutezat nici să adauge la ele, nici să scoată din ele, ci este înnăscut tuturor iudeilor, chiar de la nașterea lor, să le socotească învățăturile lui Dumnezeu și să rămână în ele și, la nevoie, să moară cu bucurie pentru ele. Aceste spuse ale istoricului am socotit că pot fi introduse cu folos în această legătură."},{"v":6,"t":"O altă lucrare de nu puțin merit a fost alcătuită de același scriitor, Despre supremația rațiunii, pe care unii au numit-o Macabaicum, pentru că cuprinde o povestire despre luptele acelor evrei care s-au luptat bărbătește pentru adevărata religie, după cum se povestește în cărțile numite Macabei."},{"v":7,"t":"Și la sfârșitul cărții a douăzecea a Antichităților sale, Josephus însuși lasă să se înțeleagă că avusese de gând să scrie o lucrare în patru cărți despre Dumnezeu și existența Lui, după părerile tradiționale ale iudeilor, și despre legi, de ce îngăduie unele lucruri, în timp ce opresc altele. Și același scriitor pomenește în lucrările lui și alte cărți scrise de el însuși."},{"v":8,"t":"Pe lângă aceste lucruri, este cuvenit să citez și cuvintele care se găsesc la încheierea Antichităților lui, în întărirea mărturiei pe care am luat-o din povestirile lui. În acel loc îl atacă pe Iustus din Tiberiada, care, ca și el, încercase să scrie o istorie a întâmplărilor contemporane, pe motiv că nu scrisese cu adevăr. După ce a adus multe alte învinuiri omului, continuă în aceste cuvinte:"},{"v":9,"t":"Eu, într-adevăr, nu m-am temut în privința scrierilor mele cum te-ai temut tu, ci, dimpotrivă, am înfățișat cărțile mele înseși împăraților când întâmplările erau aproape sub ochii oamenilor. Căci eram conștient că păstrasem adevărul în povestirea mea și de aceea nu am fost înșelat în așteptarea mea de a căpăta mărturia lor."},{"v":10,"t":"Și mi-am înfățișat istoria și multor altora, dintre care unii fuseseră de față la război, ca, de pildă, regele Agrippa și unele rude ale lui."},{"v":11,"t":"Căci împăratul Tit dorea atât de mult ca cunoașterea întâmplărilor să fie împărtășită oamenilor numai prin istoria mea încât a pus întărirea mâinii lui pe cărți și a poruncit să fie publicate. Și regele Agrippa a scris șaizeci și două de epistole care mărturiseau sinceritatea povestirii mele. Dintre aceste epistole Josephus alipește două. Dar aceasta va ajunge despre el. Să mergem acum mai departe cu istoria noastră."}];
window.LIB_LAZY["eusebiu-istoria#51"]=[{"v":1,"t":"După martiriul lui Iacov și cucerirea Ierusalimului care a urmat îndată, se spune că cei dintre apostolii și ucenicii Domnului care erau încă în viață s-au adunat din toate părțile cu cei care erau rude ale Domnului după trup (căci și cei mai mulți dintre ei erau încă în viață) ca să se sfătuiască cine este vrednic să-i urmeze lui Iacov."},{"v":2,"t":"Toți, într-un glas, au rostit că Simeon, fiul lui Cleopa, despre care pomenește și Evanghelia, este vrednic de scaunul episcopal al acelei parohii. Era văr, după cum se spune, al Mântuitorului. Căci Hegesip însemnează că Cleopa era fratele lui Iosif."}];
window.LIB_LAZY["eusebiu-istoria#52"]=[{"v":1,"t":"El povestește și că Vespasian, după cucerirea Ierusalimului, a dat poruncă să fie căutați toți cei care aparțineau neamului lui David, ca niciunul din neamul împărătesc să nu mai rămână între iudei; și în urma aceasta o foarte cumplită prigoană a atârnat din nou peste iudei."}];
window.LIB_LAZY["eusebiu-istoria#53"]=[{"v":1,"t":"După ce Vespasian domnise zece ani, i-a urmat fiul său Tit. În al doilea an al domniei lui, Lin, care fusese episcop al bisericii Romei doisprezece ani, și-a dat slujba lui Anencletus. Dar lui Tit i-a urmat fratele său Domițian, după ce domnise doi ani și tot atâtea luni."}];
window.LIB_LAZY["eusebiu-istoria#54"]=[{"v":1,"t":"În al patrulea an al lui Domițian, Anian, primul episcop al parohiei Alexandriei, a murit după ce ținuse slujba douăzeci și doi de ani și i-a urmat Abilius, al doilea episcop."}];
window.LIB_LAZY["eusebiu-istoria#55"]=[{"v":1,"t":"În al doisprezecelea an al aceleiași domnii, Clement i-a urmat lui Anencletus, după ce acesta fusese episcop al bisericii Romei doisprezece ani. Apostolul, în Epistola către Filipeni, ne înștiințează că acest Clement era împreună-lucrătorul lui. Cuvintele lui sunt următoarele: „Cu Clement și cu restul împreună-lucrătorilor mei, ale căror nume sunt în cartea vieții.”"}];
window.LIB_LAZY["eusebiu-istoria#56"]=[{"v":1,"t":"Există o epistolă a acestui Clement, care este recunoscută ca autentică, este de oarecare lungime și de un merit remarcabil. A scris-o în numele bisericii Romei către biserica Corintului, când se ridicase o răzvrătire în aceasta din urmă. Știm că și această epistolă a fost folosită public în foarte multe biserici, și în vremurile de mai înainte, și în ale noastre. Și că într-adevăr a avut loc o răzvrătire în biserica Corintului în vremea pomenită, Hegesip este un martor vrednic de încredere."}];
window.LIB_LAZY["eusebiu-istoria#57"]=[{"v":1,"t":"Domițian, după ce a arătat mare cruzime față de mulți și a dat nedrept la moarte un număr nu mic de oameni de neam bun și de seamă la Roma și a izgonit fără pricină și a confiscat averile multor altor oameni vestiți, a ajuns în cele din urmă urmaș al lui Nero în ura și dușmănia față de Dumnezeu. A fost, în fapt, al doilea care a stârnit o prigoană împotriva noastră, deși tatăl său Vespasian nu întreprinsese nimic vătămător pentru noi."}];
window.LIB_LAZY["eusebiu-istoria#58"]=[{"v":1,"t":"Se spune că în această prigoană apostolul și evanghelistul Ioan, care era încă în viață, a fost osândit să locuiască în insula Patmos din pricina mărturiei lui pentru cuvântul dumnezeiesc."},{"v":2,"t":"Irineu, în cartea a cincea a lucrării sale Împotriva ereziilor, unde discută numărul numelui lui Antihrist care este dat în așa-numita Apocalipsă a lui Ioan, vorbește astfel despre el:"},{"v":3,"t":"„Dacă ar fi fost necesar ca numele lui să fie vestit pe față în timpul de acum, ar fi fost declarat de cel care a văzut descoperirea. Căci ea a fost văzută nu de mult, ci aproape în generația noastră, la sfârșitul domniei lui Domițian.”"},{"v":4,"t":"Într-atât, într-adevăr, a înflorit în acel timp învățătura credinței noastre încât chiar acei scriitori care erau departe de religia noastră nu au șovăit să pomenească în istoriile lor prigoana și martiriile care au avut loc în timpul ei."},{"v":5,"t":"Și ei au arătat într-adevăr cu exactitate vremea. Căci au însemnat că în al cincisprezecelea an al lui Domițian, Flavia Domitila, fiica unei surori a lui Flaviu Clement, care în acel timp era unul dintre consulii Romei, a fost izgonită cu mulți alții în insula Pontia în urma mărturiei date lui Hristos."}];
window.LIB_LAZY["eusebiu-istoria#59"]=[{"v":1,"t":"Dar când acest același Domițian a poruncit să fie omorâți urmașii lui David, o veche tradiție spune că unii dintre eretici au adus învinuire împotriva urmașilor lui Iuda (despre care se spune că a fost frate al Mântuitorului după trup), pe motiv că erau din neamul lui David și erau în rudenie cu Hristos însuși. Hegesip povestește aceste fapte în cuvintele următoare."}];
window.LIB_LAZY["eusebiu-istoria#60"]=[{"v":1,"t":"Din familia Domnului mai trăiau încă nepoții lui Iuda, despre care se spune că a fost fratele Domnului după trup."},{"v":2,"t":"S-a dat de știre că aparțineau familiei lui David și au fost aduși la împăratul Domițian de către evocat. Căci Domițian se temea de venirea lui Hristos, după cum se temuse și Irod. Și i-a întrebat dacă sunt urmași ai lui David și ei au mărturisit că sunt. Apoi i-a întrebat câtă avere au sau câți bani stăpânesc. Și amândoi au răspuns că nu au decât nouă mii de dinari, din care jumătate aparținea fiecăruia dintre ei."},{"v":4,"t":"Și această avere nu consta din argint, ci dintr-o bucată de pământ care cuprindea numai treizeci și nouă de pogoane și din care își scoteau dările și se întrețineau cu propria lor muncă."},{"v":5,"t":"Apoi și-au arătat mâinile, arătând asprimea trupurilor lor și bătăturile produse pe mâinile lor de munca neîntreruptă, ca dovadă a propriei lor munci."},{"v":6,"t":"Și când au fost întrebați despre Hristos și împărăția Lui, de ce fel era și unde și când avea să se arate, au răspuns că nu era o împărăție vremelnică, nici pământească, ci una cerească și îngerească, care se va arăta la sfârșitul lumii, când El va veni în slavă să judece vii și morți și să dea fiecăruia după faptele lui."},{"v":7,"t":"La auzul acestora, Domițian nu a dat nicio hotărâre împotriva lor, ci, disprețuindu-i ca pe unii de nicio seamă, le-a dat drumul și printr-un decret a pus capăt prigoanei Bisericii."},{"v":8,"t":"Dar când au fost eliberați, au cârmuit bisericile pentru că erau martori și erau și rude ale Domnului. Și, pacea fiind întemeiată, au trăit până în vremea lui Traian. Aceste lucruri sunt povestite de Hegesip."},{"v":9,"t":"Tertulian a pomenit și el pe Domițian în cuvintele următoare: „Domițian, care avea și el o parte din cruzimea lui Nero, a încercat odată să facă același lucru pe care l-a făcut acela. Dar, pentru că avea, socotesc, oarecare minte, a încetat foarte curând și chiar i-a chemat înapoi pe cei pe care îi izgonise.”"},{"v":10,"t":"Dar după ce Domițian domnise cincisprezece ani și lui Nerva i-a urmat la imperiu, Senatul roman, după scriitorii care însemnează istoria acelor zile, a votat ca cinstirile lui Domițian să fie anulate și cei care fuseseră izgoniți pe nedrept să se întoarcă la casele lor și să li se dea înapoi averile."},{"v":11,"t":"În acest timp apostolul Ioan s-a întors din surghiunul său din insulă și și-a așezat sălașul la Efes, după o veche tradiție creștină."}];
window.LIB_LAZY["eusebiu-istoria#61"]=[{"v":1,"t":"După ce Nerva domnise ceva mai mult de un an, i-a urmat Traian. În primul an al domniei lui, Abilius, care cârmuise biserica Alexandriei treisprezece ani, a fost urmat de Cerdon."},{"v":2,"t":"El a fost al treilea care a condus acea biserică după Anian, care fusese cel dintâi. În acel timp Clement cârmuia încă biserica Romei, fiind și el al treilea care a ținut episcopatul acolo după Pavel și Petru."},{"v":3,"t":"Lin a fost cel dintâi și după el a venit Anencletus."}];
window.LIB_LAZY["eusebiu-istoria#62"]=[{"v":1,"t":"În acest timp Ignatie era cunoscut ca al doilea episcop al Antiohiei, Evodiu fiind cel dintâi. Simeon, de asemenea, era în acel timp al doilea cârmuitor al bisericii din Ierusalim, fratele Mântuitorului nostru fiind cel dintâi."}];
window.LIB_LAZY["eusebiu-istoria#63"]=[{"v":1,"t":"În acel timp apostolul și evanghelistul Ioan, cel pe care îl iubea Isus, trăia încă în Asia și cârmuia bisericile acelei regiuni, întorcându-se după moartea lui Domițian din surghiunul din insulă."},{"v":2,"t":"Și că era încă în viață în acel timp se poate stabili prin mărturia a doi martori. Ar trebui să fie vrednici de încredere cei care au păstrat ortodoxia Bisericii; și astfel erau, într-adevăr, Irineu și Clement Alexandrinul."},{"v":3,"t":"Cel dintâi, în cartea a doua a lucrării sale Împotriva ereziilor, scrie astfel: „Și toți bătrânii care s-au împărtășit cu Ioan, ucenicul Domnului, în Asia, mărturisesc că Ioan le-a dat-o lor. Căci a rămas printre ei până în vremea lui Traian.”"},{"v":4,"t":"Și în cartea a treia a aceleiași lucrări atestă același lucru în cuvintele următoare: „Dar și biserica din Efes, care a fost întemeiată de Pavel și unde Ioan a rămas până în vremea lui Traian, este un martor credincios al tradiției apostolice.”"},{"v":5,"t":"Clement, de asemenea, în cartea lui intitulată Ce bogat se poate mântui?, arată vremea și alipește o povestire foarte atrăgătoare pentru cei care se desfată să audă ce este frumos și folositor. Ia și citește povestirea care sună astfel:"},{"v":6,"t":"Ascultă o istorisire, care nu este o simplă istorisire, ci o povestire despre apostolul Ioan, care a fost transmisă și păstrată în amintire. Căci, când, după moartea tiranului, s-a întors din insula Patmos la Efes, a plecat, la invitația lor, în ținuturile învecinate ale neamurilor, ca să rânduiască episcopi în unele locuri, în alte locuri să rânduiască biserici întregi, în altele să aleagă pentru slujbă pe unul dintre cei arătați de Duhul."},{"v":7,"t":"Când a ajuns într-una dintre cetățile nu departe (al cărei nume îl dau unii), și a mângâiat pe frați în alte privințe, s-a întors în cele din urmă către episcopul care fusese rânduit și, văzând un tânăr de statură puternică, de înfățișare plăcută și de fire înfocată, a zis: «Pe acesta ți-l încredințez cu toată seriozitatea în prezența Bisericii și cu Hristos ca martor.» Și când episcopul a primit sarcina și a făgăduit totul, el a repetat aceeași poruncă cu chemarea acelorași martori și a plecat apoi la Efes."},{"v":8,"t":"Dar prezbiterul, luând acasă pe tânărul care i-a fost încredințat, l-a crescut, l-a păstrat, l-a îngrijit și, în sfârșit, l-a botezat. După aceasta și-a slăbit grija și vigilența mai aspră, cu gândul că, punându-i pecetea Domnului, îi dăduse o ocrotire desăvârșită."},{"v":9,"t":"Dar niște tineri de vârsta lui, leneși și destrăbălați și deprinși cu fapte rele, l-au stricat când a fost astfel eliberat prea devreme de frâu. La început l-au ademenit cu ospețe costisitoare; apoi, când ieșeau noaptea la furt, l-au luat cu ei și, în cele din urmă, au cerut ca el să se unească cu ei într-o crimă mai mare."},{"v":10,"t":"S-a deprins treptat cu asemenea practici și, din pricina fermității caracterului său, părăsind calea dreaptă și luând frâul în dinți ca un cal tare în gură și puternic, s-a năpustit cu atât mai violent în adâncuri."},{"v":11,"t":"Și în cele din urmă, deznădăjduind de mântuirea în Dumnezeu, nu s-a mai gândit la lucruri mărunte, ci, săvârșind vreo mare crimă, de vreme ce era acum pierdut odată pentru totdeauna, se aștepta să sufere aceeași soartă cu ceilalți. Luându-i, deci, și alcătuind o ceată de tâlhari, a devenit un îndrăzneț căpitan de bandiți, cel mai violent, cel mai însetat de sânge, cel mai crud dintre toți."},{"v":12,"t":"Timpul a trecut și, apărând o oarecare nevoie, au trimis după Ioan. Dar el, după ce a rânduit celelalte treburi pentru care venise, a zis: «Haide, episcope, dă-ne înapoi depozitul pe care ți l-am încredințat și eu, și Hristos, biserica peste care prezidezi fiind martoră.»"},{"v":13,"t":"Dar episcopul s-a încurcat la început, socotind că este învinuit pe nedrept în privința unor bani pe care nu-i primise și nu putea nici să creadă învinuirea despre ce nu avea, nici să nu-l creadă pe Ioan. Dar când a spus: «Cer pe tânăr și sufletul fratelui», bătrânul, gemând adânc și izbucnind totodată în lacrimi, a zis: «Este mort.» «Cum și ce fel de moarte?» «Este mort pentru Dumnezeu», a zis el; «căci s-a făcut rău și părăsit și, în cele din urmă, tâlhar. Și acum, în loc de biserică, bântuie muntele cu o ceată ca el.»"},{"v":14,"t":"Dar Apostolul și-a rupt hainele și, lovindu-se în cap cu mare tânguire, a zis: «Frumoasă pază am lăsat sufletului unui frate! Dar să mi se aducă un cal și să-mi arate cineva drumul.» A plecat de la biserică așa cum era și, ajungând la locul acela, a fost luat prizonier de avanpostul tâlharilor."},{"v":15,"t":"El, totuși, nu a fugit și nu a făcut rugăminte, ci a strigat: «Pentru aceasta am venit; duceți-mă la căpitanul vostru.»"},{"v":16,"t":"Acesta, între timp, aștepta, înarmat cum era. Dar când l-a recunoscut pe Ioan apropiindu-se, s-a întors cu rușine ca să fugă."},{"v":17,"t":"Dar Ioan, uitându-și vârsta, l-a urmărit cu toată puterea, strigând: «De ce, fiul meu, fugi de mine, de propriul tău tată, neînarmat, bătrân? Fie-ți milă de mine, fiul meu; nu te teme; ai încă nădejde de viață. Voi da socoteală lui Hristos pentru tine. Dacă va fi nevoie, voi îndura de bunăvoie moartea ta, după cum Domnul a îndurat moartea pentru noi. Pentru tine îmi voi da viața. Oprește-te, crede; Hristos m-a trimis.»"},{"v":18,"t":"Și el, când a auzit, s-a oprit întâi și s-a uitat în jos; apoi și-a aruncat armele și apoi a tremurat și a plâns amarnic. Și când bătrânul s-a apropiat, l-a îmbrățișat, făcând mărturisire cu tânguiri cât a putut, botezându-se a doua oară cu lacrimi și ascunzând numai dreapta lui."},{"v":19,"t":"Dar Ioan, făgăduind și încredințându-l pe jurământ că va găsi iertare la Mântuitorul, l-a rugat, a căzut în genunchi, a sărutat chiar dreapta lui, ca și cum ar fi fost acum curățită de pocăință, și l-a dus înapoi la biserică. Și mijlocind pentru el cu rugăciuni din belșug și luptându-se laolaltă cu el în posturi neîntrerupte și supunându-i mintea cu felurite cuvinte, nu a plecat, după cum se spune, până nu l-a adus înapoi în biserică, dând o mare pildă de adevărată pocăință și o mare dovadă de renaștere, un trofeu al unei învieri vizibile."}];
window.LIB_LAZY["eusebiu-istoria#64"]=[{"v":1,"t":"Acest extras din Clement l-am inserat aici de dragul istoriei și spre folosul cititorilor mei. Să arătăm acum scrierile necontestate ale acestui apostol."},{"v":2,"t":"Și mai întâi de toate, Evanghelia lui, care este cunoscută tuturor bisericilor de sub cer, trebuie recunoscută ca autentică. Că a fost pusă cu bun temei de cei din vechime pe locul al patrulea, după celelalte trei Evanghelii, se poate face vădit în chipul următor."},{"v":3,"t":"Acei mari oameni cu adevărat dumnezeiești, mă refer la apostolii lui Hristos, erau curățiți în viața lor și împodobiți cu orice virtute a sufletului, dar erau necultivați în vorbire. Erau încrezători, într-adevăr, în încrederea lor în puterea dumnezeiască și făcătoare de minuni care le fusese dată de Mântuitorul, dar nu știau cum și nici nu se încercau să vestească învățăturile Învățătorului lor într-un limbaj studiat și artistic, ci, folosind numai dovada Duhului dumnezeiesc, care lucra cu ei, și puterea făcătoare de minuni a lui Hristos, care se arăta prin ei, au publicat cunoașterea împărăției cerurilor în toată lumea, luând puțină seamă la alcătuirea scrierilor."},{"v":4,"t":"Și aceasta o făceau pentru că erau ajutați în slujba lor de unul mai mare decât omul. Pavel, de pildă, care i-a întrecut pe toți în vigoarea expresiei și bogăția gândirii, nu a pus în scris mai mult decât cele mai scurte epistole, deși avea nenumărate lucruri tainice de împărtășit, căci ajunsese chiar până la vedeniile celui de-al treilea cer, fusese dus până la raiul lui Dumnezeu și fusese socotit vrednic să audă acolo cuvinte de nespus."},{"v":5,"t":"Și restul urmașilor Mântuitorului nostru, cei doisprezece apostoli, cei șaptezeci de ucenici și nenumărați alții pe lângă ei, nu erau neștiutori de aceste lucruri. Totuși, dintre toți ucenicii Domnului, numai Matei și Ioan ne-au lăsat însemnări scrise și ei, după cum spune tradiția, au fost duși să scrie numai sub apăsarea nevoii."},{"v":6,"t":"Căci Matei, care predicase la început evreilor, când era pe cale să meargă la alte popoare, și-a pus Evanghelia în scris în limba lui maternă și a despăgubit astfel pe cei pe care era silit să-i părăsească pentru pierderea prezenței lui."},{"v":7,"t":"Și când Marcu și Luca își publicaseră deja Evangheliile, se spune că Ioan, care își petrecuse tot timpul vestind Evanghelia prin viu grai, a trecut în cele din urmă să scrie pentru următoarea pricină. Cele trei Evanghelii deja pomenite ajungând în mâinile tuturor și în ale lui, se spune că le-a primit și a mărturisit sinceritatea lor; dar că le lipsea o povestire a faptelor făcute de Hristos la începutul slujirii Lui."},{"v":8,"t":"Și aceasta este într-adevăr adevărat. Căci este vădit că cei trei evangheliști au însemnat numai faptele făcute de Mântuitorul timp de un an după închiderea în temniță a lui Ioan Botezătorul și au arătat aceasta la începutul povestirii lor."},{"v":9,"t":"Căci Matei, după postul de patruzeci de zile și ispitirea care a urmat, arată cronologia lucrării sale când spune: „Dar când a auzit că Ioan a fost dat în mâini, S-a retras din Iudeea în Galileea.” (Matei 4:12)"},{"v":10,"t":"Marcu spune la fel: „Dar după ce Ioan a fost dat în mâini, Isus a venit în Galileea.” (Marcu 1:14) Și Luca, înainte de a începe povestirea faptelor lui Isus, arată în același chip vremea, când spune că Irod, „adăugând la toate faptele rele pe care le făcuse, a închis pe Ioan în temniță”. (Luca 3:20)"},{"v":11,"t":"Se spune, deci, că apostolul Ioan, fiind rugat să facă aceasta din această pricină, a dat în Evanghelia lui o povestire despre perioada care fusese omisă de evangheliștii dinainte și despre faptele făcute de Mântuitorul în acea perioadă; adică despre cele care s-au făcut înainte de închiderea Botezătorului în temniță. Și aceasta este arătată de el, se spune, în cuvintele următoare: „Acest început de minuni l-a făcut Isus”; și iarăși când se referă la Botezător, în mijlocul faptelor lui Isus, ca botezând încă la Enon, lângă Salim (Ioan 3:23); unde arată lucrul limpede în cuvintele: „Căci Ioan nu fusese încă aruncat în temniță.”"},{"v":12,"t":"Ioan, deci, în Evanghelia lui, însemnează faptele lui Hristos care s-au săvârșit înainte ca Botezătorul să fie aruncat în temniță, dar ceilalți trei evangheliști pomenesc întâmplările care au avut loc după acel timp."},{"v":13,"t":"Cel care înțelege aceasta nu mai poate socoti că Evangheliile sunt în neînțelegere una cu alta, de vreme ce Evanghelia după Ioan cuprinde primele fapte ale lui Hristos, în timp ce celelalte dau o povestire a părții de mai târziu a vieții Lui. Și genealogia Mântuitorului nostru după trup Ioan a omis-o foarte firesc, pentru că fusese deja dată de Matei și Luca, și a început cu învățătura dumnezeirii Lui, care i-a fost, ca să zic așa, păstrată lui, ca unuia superior lor, de Duhul dumnezeiesc."},{"v":14,"t":"Aceste lucruri pot ajunge, pe care le-am spus despre Evanghelia lui Ioan. Pricina care a dus la alcătuirea Evangheliei lui Marcu a fost deja arătată de noi."},{"v":15,"t":"Dar cât despre Luca, la începutul Evangheliei lui, el însuși arată pricinile care l-au dus să o scrie. Spune că, de vreme ce mulți alții se apucaseră cu mai multă nechibzuință să alcătuiască o povestire a întâmplărilor despre care el căpătase cunoaștere deplină, el însuși, simțind nevoia de a ne elibera de părerile lor nesigure, a dat în propria lui Evanghelie o povestire exactă a acelor întâmplări despre care aflase tot adevărul, fiind ajutat de apropierea și șederea lui cu Pavel și de cunoștința cu restul apostolilor."},{"v":16,"t":"Atât despre povestirea noastră în aceste privințe. Dar la un loc mai potrivit ne vom încerca să arătăm, prin citate din cei din vechime, ce au spus alții despre ele."},{"v":17,"t":"Dar dintre scrierile lui Ioan, nu numai Evanghelia lui, ci și cea dintâi dintre epistolele lui a fost primită fără dispută și acum, și în vremurile vechi. Dar celelalte două sunt contestate."},{"v":18,"t":"În privința Apocalipsei, părerile celor mai mulți oameni sunt încă împărțite. Dar la vremea cuvenită și această chestiune va fi hotărâtă din mărturia celor din vechime."}];
window.LIB_LAZY["eusebiu-istoria#65"]=[{"v":1,"t":"Deoarece ne ocupăm de acest subiect, este cuvenit să rezumăm scrierile Noului Testament care au fost deja pomenite. Întâi trebuie pusă sfânta patrime a Evangheliilor; după ele, Faptele Apostolilor."},{"v":2,"t":"După aceasta trebuie socotite epistolele lui Pavel; în ordine, trebuie păstrată cea dintâi epistolă a lui Ioan care există și, de asemenea, epistola lui Petru. După ele trebuie pusă, dacă într-adevăr pare cuvenit, Apocalipsa lui Ioan, despre care vom da părerile diferite la vremea potrivită. Acestea aparțin, deci, scrierilor primite."},{"v":3,"t":"Printre scrierile contestate, care sunt totuși recunoscute de mulți, se găsesc așa-numita epistolă a lui Iacov și cea a lui Iuda, de asemenea a doua epistolă a lui Petru și cele care se numesc a doua și a treia a lui Ioan, fie că aparțin evanghelistului, fie altei persoane cu același nume."},{"v":4,"t":"Printre scrierile respinse trebuie socotite și Faptele lui Pavel și așa-numitul Păstor și Apocalipsa lui Petru și, pe lângă acestea, epistola lui Barnaba care există și așa-numitele Învățături ale apostolilor; și, pe lângă acestea, după cum am spus, Apocalipsa lui Ioan, dacă pare cuvenit, pe care unii, cum am spus, o resping, dar alții o numără printre cărțile primite."},{"v":5,"t":"Și printre acestea unii au pus și Evanghelia după evrei, cu care se desfată mai ales cei dintre evrei care au primit pe Hristos. Și toate acestea pot fi numărate printre cărțile contestate."},{"v":6,"t":"Dar ne-am simțit totuși siliți să dăm un catalog și al acestora, deosebind acele lucrări care, după tradiția bisericească, sunt adevărate și autentice și primite în mod obișnuit, de celelalte care, deși nu sunt canonice, ci contestate, sunt totuși, în același timp, cunoscute celor mai mulți dintre scriitorii bisericești — ne-am simțit siliți să dăm acest catalog ca să putem cunoaște și aceste lucrări și pe cele citate de eretici sub numele apostolilor, incluzând, de pildă, asemenea cărți ca Evangheliile lui Petru, Toma, Matia sau ale oricăror altora pe lângă ele, și Faptele lui Andrei și Ioan și ale celorlalți apostoli, pe care nimeni din șirul scriitorilor bisericești nu le-a socotit vrednice de pomenire în scrierile lui."},{"v":7,"t":"Și mai mult, caracterul stilului este în dezacord cu obiceiul apostolic, iar atât gândurile, cât și scopul lucrurilor care sunt povestite în ele sunt atât de cu totul în neînvoire cu adevărata ortodoxie încât se arată limpede că sunt născociri ale ereticilor. De aceea nu trebuie puse nici măcar printre scrierile respinse, ci toate trebuie lepădate ca absurde și nelegiuite. Să mergem acum mai departe cu istoria noastră."}];
window.LIB_LAZY["eusebiu-istoria#66"]=[{"v":1,"t":"Menandru, care i-a urmat lui Simon Magul, s-a arătat în purtarea lui un alt unealtă a puterii diavolești, nu mai prejos decât cel dintâi. Era și el samaritean și și-a dus vrăjitoriile nu mai puțin departe decât învățătorul lui și, în același timp, se desfăta cu povești și mai minunate decât el."},{"v":2,"t":"Căci spunea că el însuși este Mântuitorul, care fusese trimis jos din eoni nevăzuți pentru mântuirea oamenilor; și învăța că nimeni nu poate câștiga stăpânirea asupra îngerilor înșiși creatori ai lumii dacă nu a trecut mai întâi prin disciplina magică împărtășită de el și nu a primit botez de la el. Cei socotiți vrednici de aceasta aveau să se împărtășească chiar în viața de acum de nemurire neîncetată și nu aveau să moară niciodată, ci aveau să rămână aici pentru totdeauna și, fără să îmbătrânească, să devină nemuritori. Aceste fapte se pot afla ușor din lucrările lui Irineu."},{"v":3,"t":"Și Iustin, în pasajul în care pomenește pe Simon, dă o povestire și despre acest om, în cuvintele următoare: „Și știm că un anume Menandru, care era tot samaritean, din satul Caparatea, a fost ucenic al lui Simon și că și el, fiind mânat de demoni, a venit la Antiohia și a amăgit pe mulți prin arta lui magică. Și a convins pe urmașii lui că nu vor muri. Și mai sunt încă unii dintre ei care afirmă aceasta.”"},{"v":4,"t":"Și era într-adevăr un meșteșug al diavolului să se silească, prin asemenea vrăjitori, care luau numele de creștini, să defaime marea taină a evlaviei prin artă magică și, prin ei, să facă de râs învățăturile Bisericii despre nemurirea sufletului și învierea morților. Dar cei care i-au ales pe acești oameni ca mântuitori ai lor au căzut de la adevărata nădejde."}];
window.LIB_LAZY["eusebiu-istoria#67"]=[{"v":1,"t":"Demonul cel rău, totuși, neputând să smulgă pe alții de la credincioșia față de Hristosul lui Dumnezeu, i-a găsit totuși ușor de atins într-o altă direcție și i-a adus astfel la scopurile lui. Cei din vechime au numit pe acești oameni, destul de potrivit, ebioniți, pentru că aveau păreri sărace și josnice despre Hristos."},{"v":2,"t":"Căci Îl socoteau un om simplu și de rând, care fusese îndreptățit numai pentru virtutea Lui superioară și care era rodul împreunării unui om cu Maria. După părerea lor, păzirea legii ceremoniale era cu totul necesară, pe motiv că nu se puteau mântui numai prin credința în Hristos și printr-o viață potrivită."},{"v":3,"t":"Erau, totuși, și alții, pe lângă aceștia, de același nume, dar care evitau credințele ciudate și absurde ale celor dintâi și nu tăgăduiau că Domnul S-a născut dintr-o fecioară și din Duhul Sfânt. Dar totuși, deoarece refuzau și ei să recunoască că a preexistat, fiind Dumnezeu, Cuvânt și Înțelepciune, s-au abătut în nelegiuirea celor dintâi, mai ales când s-au silit și ei, ca aceia, să păzească cu strictețe închinarea trupească a legii."},{"v":4,"t":"Acești oameni socoteau, pe lângă aceasta, că este necesar să respingă toate epistolele apostolului, pe care îl numeau un apostat de la lege; și se slujeau numai de așa-numita Evanghelie după evrei și socoteau puțin restul."},{"v":5,"t":"Sabatul și restul disciplinei iudeilor le păzeau întocmai ca ei, dar în același timp, ca și noi, prăznuiau zilele Domnului ca pomenire a învierii Mântuitorului."},{"v":6,"t":"De aceea, ca urmare a unei asemenea purtări, au primit numele de ebioniți, care însemna sărăcia înțelegerii lor. Căci acesta este numele cu care este numit un om sărac între evrei."}];
window.LIB_LAZY["eusebiu-istoria#68"]=[{"v":1,"t":"Am înțeles că în acest timp s-a arătat Cerint, autorul altei erezii. Caiu, ale cărui cuvinte le-am citat mai sus, în Disputarea care îi este atribuită, scrie astfel despre acest om:"},{"v":2,"t":"„Dar și Cerint, prin descoperiri pe care se preface că le-ar fi scris un mare apostol, ne aduce înainte lucruri minunate pe care pretinde pe nedrept că i le-au arătat îngerii; și spune că după înviere împărăția lui Hristos va fi întemeiată pe pământ și că trupul care locuiește în Ierusalim va fi din nou supus poftelor și plăcerilor. Și, fiind un dușman al Scripturilor lui Dumnezeu, afirmă, cu scopul de a amăgi oamenii, că va fi o perioadă de o mie de ani pentru ospețe de nuntă.”"},{"v":3,"t":"Și Dionisie, care a fost episcop al parohiei Alexandriei în vremea noastră, în cartea a doua a lucrării sale Despre făgăduințe, unde spune unele lucruri despre Apocalipsa lui Ioan pe care le scoate din tradiție, pomenește pe același om în cuvintele următoare:"},{"v":4,"t":"Dar (se spune că) Cerint, care a întemeiat secta numită după el cerintiană, dorind o autoritate cinstită pentru născocirea lui, a pus în frunte numele ei. Căci învățătura pe care a predat-o era aceasta: că împărăția lui Hristos va fi una pământească."},{"v":5,"t":"Și fiind el însuși dedat plăcerilor trupului și cu totul senzual în firea lui, a visat că acea împărăție va consta în lucrurile pe care le dorea, anume în desfătările pântecelui și ale patimii sexuale, adică în mâncat și băut și căsătorit și în sărbători și jertfe și înjunghierea de victime, sub chipul cărora socotea că își poate îngădui poftele cu mai bună față."},{"v":6,"t":"Acestea sunt cuvintele lui Dionisie. Dar Irineu, în cartea întâi a lucrării sale Împotriva ereziilor, dă niște învățături mincinoase și mai urâte ale aceluiași om și în cartea a treia povestește o istorisire care merită să fie însemnată. Spune, pe autoritatea lui Policarp, că apostolul Ioan a intrat odată într-o baie să se scalde; dar, aflând că Cerint era înăuntru, a sărit de la locul lui și a ieșit în fugă pe ușă, căci nu putea suferi să rămână sub același acoperiș cu el. Și i-a sfătuit pe cei care erau cu el să facă la fel, zicând: „Să fugim, ca nu cumva baia să se prăbușească; căci Cerint, dușmanul adevărului, este înăuntru.”"}];
window.LIB_LAZY["eusebiu-istoria#69"]=[{"v":1,"t":"În acest timp s-a arătat așa-numita sectă a nicolaiților și a durat foarte puțin timp. Se face pomenire de ea în Apocalipsa lui Ioan. Se lăudau că autorul sectei lor este Nicolae, unul dintre diaconii care, cu Ștefan, au fost rânduiți de apostoli ca să slujească săracilor. Clement Alexandrinul, în cartea a treia a Stromatelor sale, povestește următoarele lucruri despre el."},{"v":2,"t":"Se spune că avea o nevastă frumoasă și, după înălțarea Mântuitorului, fiind învinuit de apostoli de gelozie, a adus-o în mijlocul lor și a dat voie oricui voia să se căsătorească cu ea. Căci spun că aceasta era în acord cu acea spusă a lui, că trebuie să batjocorești trupul. Și cei care i-au urmat eresul, imitând orbește și prostește ce s-a făcut și s-a spus, săvârșesc desfrânare fără rușine."},{"v":3,"t":"Dar înțeleg că Nicolae nu a avut de-a face cu nicio altă femeie decât cu aceea cu care era căsătorit și că, în privința copiilor lui, fiicele lui au rămas în stare de fecioarie până la bătrânețe, iar fiul lui a rămas neîntinat. Dacă este așa, când și-a adus nevasta, pe care o iubea cu gelozie, în mijlocul apostolilor, se lepăda în mod vădit de patima lui; și când a folosit expresia «să batjocorești trupul», propovăduia stăpânirea de sine în fața acelor plăceri care sunt urmărite cu înfocare. Căci socotesc că, potrivit cu porunca Mântuitorului, nu voia să slujească la doi stăpâni, plăcerii și Domnului."},{"v":4,"t":"Dar se spune că și Matia a învățat în același chip că trebuie să luptăm împotriva trupului și să-l batjocorim și să nu cedăm lui de dragul plăcerii, ci să întărim sufletul prin credință și cunoștință. Atât despre cei care au încercat atunci să strice adevărul, dar care, într-un timp mai scurt decât a trebuit ca să se povestească, au ajuns cu totul stinși."}];
window.LIB_LAZY["eusebiu-istoria#70"]=[{"v":1,"t":"Clement, într-adevăr, ale cărui cuvinte tocmai le-am citat, după faptele pomenite mai sus dă o înșirare, din pricina celor care respingeau căsătoria, a apostolilor care aveau neveste. „Sau vor respinge ei”, spune el, „chiar și pe apostoli? Căci Petru și Filip au născut copii; și Filip și-a dat fiicele în căsătorie. Și Pavel nu șovăiește, într-una dintre epistolele lui, să-și salute nevasta, pe care nu o ducea cu el, ca să nu fie stânjenit în slujba lui.”"},{"v":2,"t":"Și de vreme ce am pomenit acest subiect, nu este nepotrivit să alipim o altă povestire care este dată de același autor și care merită citită. În cartea a șaptea a Stromatelor sale scrie astfel: „Se spune, deci, că atunci când fericitul Petru și-a văzut propria nevastă dusă la moarte, s-a bucurat din pricina chemării ei și a întoarcerii ei acasă și a strigat către ea foarte încurajator și mângâietor, chemând-o pe nume și zicând: «Adu-ți aminte de Domnul.» Astfel era căsătoria celor fericiți și dispoziția lor desăvârșită față de cei mai dragi ai lor.” Această povestire, fiind potrivită cu subiectul de față, am istorisit-o aici la locul ei cuvenit."}];
window.LIB_LAZY["eusebiu-istoria#71"]=[{"v":1,"t":"Vremea și chipul morții lui Pavel și a lui Petru, precum și locurile lor de îngropare, au fost deja arătate de noi."},{"v":2,"t":"Vremea morții lui Ioan a fost de asemenea dată în general, dar locul lui de îngropare este arătat de o epistolă a lui Policrate (care era episcop al parohiei Efesului), adresată lui Victor, episcopul Romei. În această epistolă îl pomenește împreună cu apostolul Filip și fiicele lui în cuvintele următoare:"},{"v":3,"t":"„Căci și în Asia au adormit mari luminători, care vor învia în ziua de pe urmă, la venirea Domnului, când va veni cu slavă din cer și va căuta pe toți sfinții. Printre aceștia este Filip, unul dintre cei doisprezece apostoli, care doarme la Hierapole, și cele două fiice ale lui, fecioare bătrâne, și o altă fiică care a trăit în Duhul Sfânt și acum se odihnește la Efes; și, pe lângă aceasta, Ioan, care a fost și martor și învățător, care s-a rezemat pe pieptul Domnului și, fiind preot, a purtat placa preoțească. El doarme și el la Efes.”"},{"v":4,"t":"Atât despre moartea lor. Și în Dialogul lui Caiu pe care l-am pomenit puțin mai sus, Proclu, împotriva căruia și-a îndreptat disputarea, în acord cu ce s-a citat, vorbește astfel despre moartea lui Filip și a fiicelor lui: „După el au fost patru prorocițe, fiicele lui Filip, la Hierapole în Asia. Mormântul lor este acolo și mormântul tatălui lor.” Aceasta este spusa lui."},{"v":5,"t":"Dar Luca, în Faptele Apostolilor, pomenește pe fiicele lui Filip, care erau în acel timp la Cezareea în Iudeea cu tatăl lor și erau cinstite cu darul proorociei. Cuvintele lui sunt următoarele: „Am venit la Cezareea; și, intrând în casa lui Filip evanghelistul, care era unul dintre cei șapte, am rămas la el. Acest om avea patru fiice, fecioare, care prorociseră.”"},{"v":6,"t":"Am înfățișat astfel în aceste pagini ce a ajuns la cunoștința noastră despre apostolii înșiși și vremea apostolică și despre scrierile sfinte pe care ni le-au lăsat, precum și despre cele care sunt disputate, dar totuși au fost folosite public de mulți în foarte multe biserici, și, pe lângă aceasta, despre cele care sunt cu totul respinse și sunt în neînvoire cu ortodoxia apostolică. După ce am făcut aceasta, să mergem acum mai departe cu istoria noastră."}];
window.LIB_LAZY["eusebiu-istoria#72"]=[{"v":1,"t":"Se povestește că după vremea lui Nero și Domițian, sub împăratul ale cărui vremuri le însemnăm acum, s-a stârnit o prigoană împotriva noastră în anumite cetăți în urma unei răscoale populare. În această prigoană am înțeles că a suferit martiriul Simeon, fiul lui Cleopa, care, după cum am arătat, a fost al doilea episcop al bisericii din Ierusalim."},{"v":2,"t":"Hegesip, ale cărui cuvinte le-am citat deja în felurite locuri, este martor și al acestui fapt. Vorbind despre anumiți eretici, adaugă că Simeon a fost învinuit de ei în acest timp; și de vreme ce era limpede că este creștin, a fost chinuit în felurite chipuri multe zile și a uimit în cel mai înalt grad chiar pe judecător și pe slujitorii lui și, în cele din urmă, a suferit o moarte asemănătoare cu a Domnului nostru."},{"v":3,"t":"Dar nu este nimic ca să-l auzi pe istoric însuși, care scrie astfel: „Unii dintre acești eretici au adus învinuire împotriva lui Simeon, fiul lui Cleopa, pe motiv că era un descendent al lui David și creștin; și astfel a suferit martiriul, la vârsta de o sută douăzeci de ani, în vremea când Traian era împărat și Atticus guvernator.”"},{"v":4,"t":"Și același scriitor spune că și învinuitorii lui, când s-au făcut căutări pentru urmașii lui David, au fost arestați ca aparținând acelei familii. Și s-ar putea presupune pe drept că Simeon era unul dintre cei care au văzut și au auzit pe Domnul, judecând după lungimea vieții lui și după faptul că Evanghelia pomenește pe Maria, nevasta lui Cleopa, care era tatăl lui Simeon, după cum s-a arătat deja."},{"v":5,"t":"Același istoric spune că mai erau și alții, coborâți dintr-unul dintre așa-numiții frați ai Mântuitorului, al cărui nume era Iuda, care, după ce au dat mărturie înaintea lui Domițian, cum s-a însemnat deja, pentru credința în Hristos, au trăit până în aceeași domnie."},{"v":6,"t":"Scrie astfel: „Au venit, deci, și au luat conducerea fiecărei biserici ca martori și ca rude ale Domnului. Și, o pace adâncă fiind întemeiată în fiecare biserică, au rămas până în domnia împăratului Traian și până când pomenitul Simeon, fiul lui Cleopa, un unchi al Domnului, a fost dat în vileag de eretici și a fost învinuit și el, în același chip, pentru aceeași pricină înaintea guvernatorului Atticus. Și după ce a fost chinuit multe zile, a suferit martiriul și toți, chiar și proconsulul, s-au minunat că, la vârsta de o sută douăzeci de ani, a putut îndura atât de mult. Și s-a dat poruncă să fie răstignit.”"},{"v":7,"t":"Pe lângă aceste lucruri, același om, povestind întâmplările acelei perioade, însemnează că Biserica rămăsese până în acel timp o fecioară curată și neîntinată, de vreme ce, dacă erau unii care încercau să strice norma sănătoasă a predicii mântuirii, zăceau până atunci ascunși în întuneric obscur."},{"v":8,"t":"Dar când sfântul colegiu al apostolilor a suferit moartea în felurite chipuri și generația celor care fuseseră socotiți vrednici să audă cu urechile lor înțelepciunea insuflată trecuse, atunci liga rătăcirii fără Dumnezeu și-a luat începutul în urma nebuniei învățătorilor eretici, care, pentru că niciunul dintre apostoli nu mai trăia, au încercat de atunci înainte, cu față îndrăzneață, să vestească, în opoziție cu predica adevărului, «cunoștința numită pe nedrept așa»."}];
window.LIB_LAZY["eusebiu-istoria#73"]=[{"v":1,"t":"O atât de mare prigoană s-a deschis în acel timp împotriva noastră în multe locuri încât Pliniu Secundus, unul dintre cei mai vestiți guvernatori, tulburat de marele număr de martiri, a comunicat cu împăratul despre mulțimea celor care erau dați la moarte pentru credința lor. În același timp, i-a dat de știre în comunicarea lui că nu auzise că ar face ceva nelegiuit sau împotriva legilor — afară de faptul că se sculau în zori și cântau imnuri lui Hristos ca unui Dumnezeu; dar că se lepădau de adulter și omor și asemenea fapte criminale și făceau toate lucrurile în acord cu legile."},{"v":2,"t":"Ca răspuns la aceasta, Traian a dat următorul decret: că neamul creștinilor să nu fie căutat, dar când este găsit să fie pedepsit. Din această pricină prigoana, care amenința să fie una foarte cumplită, a fost într-o oarecare măsură oprită, dar au rămas încă destule pretexte pentru cei care voiau să ne facă rău. Uneori poporul, alteori cârmuitorii din diferite locuri ne puneau curse, așa încât, deși nu au avut loc mari prigoane, prigoane locale s-au dus totuși în anumite provincii și mulți dintre credincioși au îndurat martiriul în felurite chipuri."},{"v":3,"t":"Povestirea am luat-o din Apologia latină a lui Tertulian pe care am pomenit-o mai sus. Traducerea sună astfel: Și într-adevăr am găsit că căutarea noastră a fost oprită. Căci când Pliniu Secundus, guvernatorul unei provincii, a osândit pe unii creștini și i-a lipsit de demnitatea lor, a fost încurcat de mulțime și nu știa ce drum să urmeze mai departe. A comunicat, deci, cu Traian, împăratul, înștiințându-l că, pe lângă nevoința lor de a jertfi, nu găsise nicio nelegiuire în ei."},{"v":4,"t":"Și a raportat și aceasta, că creștinii se sculau dimineața devreme și cântau imnuri lui Hristos ca unui Dumnezeu și, în scopul păstrării disciplinei lor, opreau omorul, adulterul, lăcomia, tâlhăria și altele asemenea. Ca răspuns la aceasta, Traian a scris că neamul creștinilor să nu fie căutat, dar când este găsit să fie pedepsit. Astfel au fost întâmplările care au avut loc în acel timp."}];
window.LIB_LAZY["eusebiu-istoria#74"]=[{"v":1,"t":"În al treilea an al domniei împăratului pomenit mai sus, Clement a încredințat cârmuirea episcopală a bisericii Romei lui Evarist și a părăsit această viață după ce supraveghease învățătura cuvântului dumnezeiesc nouă ani în total."}];
window.LIB_LAZY["eusebiu-istoria#75"]=[{"v":1,"t":"Dar când a murit și Simeon, în chipul descris, un anume iudeu cu numele Iust a urmat la scaunul episcopal din Ierusalim. El era unul dintre multele mii din tăierea împrejur care au crezut în acel timp în Hristos."}];
window.LIB_LAZY["eusebiu-istoria#76"]=[{"v":1,"t":"În acel timp Policarp, un ucenic al apostolilor, era un om de seamă în Asia, fiindu-i încredințat episcopatul bisericii din Smirna de către cei care văzuseră și auziseră pe Domnul."},{"v":2,"t":"Și în același timp Papias, episcopul parohiei Hierapolei, a devenit bine cunoscut, ca și Ignatie, care a fost ales episcop al Antiohiei, al doilea în succesiune după Petru și a cărui faimă este încă prăznuită de foarte mulți."},{"v":3,"t":"Se spune că a fost trimis din Siria la Roma și a ajuns hrană fiarelor sălbatice din pricina mărturiei lui pentru Hristos."},{"v":4,"t":"Și pe când făcea călătoria prin Asia sub cea mai strictă supraveghere ostășească, a întărit parohiile din diferitele cetăți unde se oprea prin omilii și îndemnuri prin viu grai și le-a avertizat mai presus de toate să se păzească în chip deosebit de ereziile care începeau atunci să stăpânească și le-a îndemnat să țină tare tradiția apostolilor. Pe lângă aceasta, a socotit necesar să ateste acea tradiție în scris și să-i dea o formă stabilă de dragul unei mai mari siguranțe."},{"v":5,"t":"Astfel, când a ajuns la Smirna, unde era Policarp, a scris o epistolă bisericii din Efes, în care pomenește pe Onisim, păstorul ei; și alta bisericii din Magnezia, așezată pe Meandru, în care pomenește iarăși un episcop Damas; și, în sfârșit, una bisericii din Tralles, al cărei episcop, spune el, era în acel timp Polibiu."},{"v":6,"t":"Pe lângă acestea, a scris și bisericii Romei, rugându-i să nu-i facă scăparea din martiriu și să-l lipsească astfel de nădejdea lui înfocată. În întărirea celor spuse este cuvenit să citez pe scurt din această epistolă."},{"v":7,"t":"Scrie astfel: Din Siria până la Roma mă lupt cu fiarele sălbatice, pe uscat și pe mare, noaptea și ziua, fiind legat în mijlocul a zece leoparzi, adică o ceată de ostași care devin mai răi doar când sunt bine tratați. În mijlocul nedreptăților lor, totuși, învăț mai deplin ucenicia, dar nu sunt prin aceasta îndreptățit."},{"v":8,"t":"Să mă bucur de fiarele care îmi sunt pregătite; și mă rog să le găsesc gata; ba chiar le voi momi să mă mănânce repede, ca să nu se poarte cu mine cum s-au purtat cu unii pe care au refuzat să-i atingă de frică. Și dacă nu vor vrea, le voi sili. Iertați-mă."},{"v":9,"t":"Știu ce-mi este de folos. Acum încep să fiu ucenic. Să nu mă pizmuiască nimic din cele văzute și cele nevăzute, ca să ajung la Isus Hristos. Să vină peste mine foc și cruce și atacuri de fiare sălbatice, sfâșierea oaselor, tăierea mădularelor, zdrobirea întregului trup, chinurile diavolului — să vină toate acestea peste mine, numai să ajung la Isus Hristos."},{"v":10,"t":"Aceste lucruri le-a scris din pomenita cetate către bisericile amintite. Și când a părăsit Smirna, a scris din nou din Troa către filadelfieni și către biserica din Smirna; și în chip deosebit către Policarp, care prezida această din urmă biserică. Și fiindcă îl cunoștea bine ca pe un om apostolic, i-a încredințat, ca unui păstor adevărat și bun, turma din Antiohia și l-a rugat să se îngrijească de ea cu sârguință."},{"v":11,"t":"Și același om, scriind smirnenilor, a folosit următoarele cuvinte despre Hristos, luate nu știu de unde: „Dar știu și cred că a fost în trup după înviere. Și când a venit la Petru și tovarășii lui, le-a zis: Luați, pipăiți-Mă și vedeți că nu sunt un duh necorporal. Și îndată s-au atins de El și au crezut.”"},{"v":12,"t":"Irineu cunoștea și el martiriul lui și pomenește epistolele lui în cuvintele următoare: „Cum a spus unul de-ai noștri, când a fost osândit la fiare din pricina mărturiei lui pentru Dumnezeu: Eu sunt grâul lui Dumnezeu și sunt măcinat de dinții fiarelor sălbatice, ca să fiu găsit pâine curată.”"},{"v":13,"t":"Policarp pomenește și el aceste scrisori în epistola către filipeni care îi este atribuită. Cuvintele lui sunt următoarele: „Vă îndemn, deci, pe toți să fiți ascultători și să practicați toată răbdarea pe care ați văzut-o cu ochii voștri nu numai în fericitul Ignatie și Ruf și Zosim, ci și în alții dintre voi înșivă, precum și în Pavel însuși și în restul apostolilor; fiind încredințați că toți aceștia nu au alergat în zadar, ci în credință și dreptate, și că s-au dus la locul lor cuvenit lângă Domnul, cu care au și pătimit. Căci nu au iubit lumea de acum, ci pe Cel care a murit pentru noi și a fost înviat de Dumnezeu pentru noi.”"},{"v":14,"t":"Și după aceea adaugă: Mi-ați scris, și voi, și Ignatie, că dacă merge cineva în Siria să ducă cu el scrisorile de la voi. Și aceasta o voi face dacă voi avea un prilej potrivit, fie eu însumi, fie unul pe care îl trimit ca sol și pentru voi."},{"v":15,"t":"Epistolele lui Ignatie care ne-au fost trimise de el și celelalte pe care le aveam cu noi vi le-am trimis, după cum ați poruncit. Sunt alipite la această epistolă și din ele veți putea căpăta mare folos. Căci cuprind credință și răbdare și orice fel de zidire care ține de Domnul nostru. Atât despre Ignatie. Dar i-a urmat Heros în episcopatul bisericii din Antiohia."}];
window.LIB_LAZY["eusebiu-istoria#77"]=[{"v":1,"t":"Printre cei vestiți în acel timp era Cuadrat, care, se spune, era renumit, împreună cu fiicele lui Filip, pentru darurile lui proorocești. Și mai erau mulți alții pe lângă aceștia care erau cunoscuți în acele zile și care ocupau primul loc între urmașii apostolilor. Și ei, fiind ucenici de seamă ai unor asemenea oameni mari, au zidit temeliile bisericilor care fuseseră puse de apostoli în fiecare loc și au predicat Evanghelia tot mai larg și au împrăștiat semințele mântuitoare ale împărăției cerurilor aproape și departe, în toată lumea."},{"v":2,"t":"Căci într-adevăr cei mai mulți dintre ucenicii acelui timp, însuflețiți de cuvântul dumnezeiesc cu o dragoste mai înfocată pentru filozofie, împliniseră deja porunca Mântuitorului și își împărțiseră bunurile celor lipsiți. Apoi, pornind în lungi călătorii, îndeplineau slujba de evangheliști, fiind plini de dorința de a predica pe Hristos celor care nu auziseră încă cuvântul credinței și de a le da Evangheliile dumnezeiești."},{"v":3,"t":"Și când nu făcuseră decât să pună temeliile credinței în locuri străine, rânduiau pe alții ca păstori și le încredințau creșterea celor aduși de curând, în timp ce ei înșiși mergeau iarăși mai departe în alte țări și neamuri, cu harul și împreună-lucrarea lui Dumnezeu. Căci foarte multe lucrări minunate se făceau prin ei prin puterea Duhului dumnezeiesc, așa încât, la prima auzire, mulțimi întregi de oameni îmbrățișau cu înfocare religia Creatorului universului."},{"v":4,"t":"Dar de vreme ce este cu neputință să înșirăm numele tuturor celor care au devenit păstori sau evangheliști în bisericile din toată lumea în epoca ce a urmat îndată apostolilor, am însemnat, cum se cuvenea, numele numai ale celor care ne-au transmis învățătura apostolică în scrieri încă existente."}];
window.LIB_LAZY["eusebiu-istoria#78"]=[{"v":1,"t":"Astfel a făcut Ignatie în epistolele pe care le-am pomenit și Clement în epistola lui, care este primită de toți și pe care a scris-o în numele bisericii Romei către biserica Corintului. În această epistolă dă multe gânduri luate din Epistola către Evrei și citează și literal unele dintre expresiile ei, arătând astfel cât se poate de limpede că nu este o lucrare recentă."},{"v":2,"t":"De aceea a părut cuvenit să fie numărată cu celelalte scrieri ale apostolului. Căci, de vreme ce Pavel scrisese evreilor în limba lor maternă, unii spun că evanghelistul Luca, alții că acest Clement însuși a tradus epistola."},{"v":3,"t":"Cea din urmă pare mai probabilă, pentru că epistola lui Clement și cea către Evrei au un caracter asemănător în privința stilului și, mai mult, pentru că gândurile cuprinse în cele două lucrări nu sunt foarte deosebite."},{"v":4,"t":"Dar trebuie observat și că se spune că există o a doua epistolă a lui Clement. Dar nu știm că aceasta este recunoscută ca cea dintâi, căci nu găsim că cei din vechime s-ar fi slujit de ea."},{"v":5,"t":"Și unii oameni au adus de curând înainte alte scrieri vorbărețe și lungi sub numele lui, cuprinzând dialoguri ale lui Petru și Apion. Dar nu s-a făcut nicio pomenire de acestea de către cei din vechime; căci nici măcar nu păstrează pecetea curată a ortodoxiei apostolice. Scrierea recunoscută a lui Clement este bine cunoscută. Am vorbit și despre lucrările lui Ignatie și Policarp."}];
window.LIB_LAZY["eusebiu-istoria#79"]=[{"v":1,"t":"Există cinci cărți ale lui Papias, care poartă titlul Tâlcuiri ale cuvintelor Domnului. Irineu le pomenește ca singurele lucrări scrise de el, în cuvintele următoare: „Aceste lucruri sunt atestate de Papias, un om din vechime care a fost ascultător al lui Ioan și tovarăș al lui Policarp, în cartea lui a patra. Căci cinci cărți au fost scrise de el.” Acestea sunt cuvintele lui Irineu."},{"v":2,"t":"Dar Papias însuși, în prefața cuvântărilor lui, nu declară în niciun chip că el însuși a fost ascultător și martor ocular al sfinților apostoli, ci arată prin cuvintele pe care le folosește că a primit învățăturile credinței de la cei care le fuseseră prieteni."},{"v":3,"t":"El spune: Dar nu voi șovăi să pun jos pentru voi, împreună cu tâlcuirile mele, orice lucruri am învățat vreodată cu grijă de la bătrâni și mi-am amintit cu grijă, garantând adevărul lor. Căci nu mi-a plăcut, ca mulțimii, de cei care vorbesc mult, ci de cei care învață adevărul; nu de cei care povestesc porunci străine, ci de cei care transmit poruncile date de Domnul credinței și izvorâte din adevărul însuși."},{"v":4,"t":"Dacă, deci, venea cineva care fusese urmaș al bătrânilor, îl întrebam despre cuvintele bătrânilor — ce a spus Andrei sau ce a spus Petru, sau ce s-a spus de Filip, sau de Toma, sau de Iacov, sau de Ioan, sau de Matei, sau de oricare alt ucenic al Domnului, și ce lucruri spun Aristion și prezbiterul Ioan, ucenicii Domnului. Căci nu socoteam că ceea ce se poate lua din cărți mi-ar folosi atât de mult cât ceea ce vine de la glasul viu și stăruitor."},{"v":5,"t":"Merită să observăm aici că numele Ioan este numărat de el de două ori. Pe cel dintâi îl pomenește în legătură cu Petru și Iacov și Matei și restul apostolilor, înțelegând limpede pe evanghelist; dar pe celălalt Ioan îl pomenește după un interval și îl pune printre alții în afara numărului apostolilor, punând pe Aristion înaintea lui, și îl numește anume prezbiter."},{"v":6,"t":"Aceasta arată că spusa celor care afirmă că au fost în Asia două persoane care purtau același nume este adevărată și că au fost două morminte în Efes, fiecare dintre ele numit, până în ziua de azi, al lui Ioan. Este important să luăm seama la aceasta. Căci este probabil că al doilea, dacă cineva nu vrea să admită că cel dintâi a fost cel care a văzut Descoperirea, care este atribuită pe nume lui Ioan."},{"v":7,"t":"Și Papias, despre care vorbim acum, mărturisește că a primit cuvintele apostolilor de la cei care i-au urmat, dar spune că a fost el însuși ascultător al lui Aristion și al prezbiterului Ioan. Cel puțin, îi pomenește adesea pe nume și dă tradițiile lor în scrierile lui. Aceste lucruri, nădăjduim, nu le-am adus noi în zadar."},{"v":8,"t":"Dar este cuvenit să alipim la cuvintele lui Papias care au fost citate alte pasaje din lucrările lui în care povestește alte întâmplări minunate pe care pretinde că le-a primit din tradiție."},{"v":9,"t":"Că apostolul Filip a locuit la Hierapole cu fiicele lui a fost deja spus. Dar trebuie notat aici că Papias, contemporanul lor, spune că a auzit o istorisire minunată de la fiicele lui Filip. Căci povestește că în vremea lui a înviat cineva din morți. Și povestește o altă istorie minunată despre Iust, poreclit Barsaba: că a băut o otravă mortală și totuși, prin harul Domnului, nu a suferit nicio vătămare."},{"v":10,"t":"Cartea Faptelor însemnează că sfinții apostoli, după înălțarea Mântuitorului, au pus înainte pe acest Iust, împreună cu Matia, și s-au rugat ca unul să fie ales în locul trădătorului Iuda, ca să le completeze numărul. Povestirea este următoarea: „Și au pus înainte doi, pe Iosif, numit Barsaba, care se numea Iust, și pe Matia; și s-au rugat și au zis.” (Fapte 1:23)"},{"v":11,"t":"Același scriitor dă și alte povestiri care, spune el, au ajuns la el prin tradiție nescrisă, anume unele pilde ciudate și învățături ale Mântuitorului și alte lucruri mai mitice."},{"v":12,"t":"La acestea aparține spusa lui că va fi o perioadă de vreo o mie de ani după învierea morților și că împărăția lui Hristos va fi întemeiată în chip material pe acest pământ. Socotesc că a căpătat aceste idei printr-o neînțelegere a povestirilor apostolice, neobservând că lucrurile spuse de ei au fost spuse tainic, în figuri."},{"v":13,"t":"Căci pare să fi fost de o înțelegere foarte limitată, după cum se poate vedea din cuvântările lui. Dar se datorează lui că atâția dintre Părinții Bisericii după el au adoptat o părere asemănătoare, invocând în sprijinul lor vechimea omului; ca, de pildă, Irineu și oricare altul care ar fi vestit păreri asemănătoare."},{"v":14,"t":"Papias dă în lucrarea lui și alte povestiri despre cuvintele Domnului pe autoritatea lui Aristion, pomenit mai sus, și tradiții transmise de prezbiterul Ioan; la care trimitem pe cei care iubesc învățătura. Dar acum trebuie să adăugăm la cuvintele lui pe care le-am citat deja tradiția pe care o dă despre Marcu, autorul Evangheliei."},{"v":15,"t":"„Și aceasta a spus-o prezbiterul: Marcu, devenind tălmaciul lui Petru, a scris cu exactitate, deși nu în ordine, tot ce-și amintea din lucrurile spuse sau făcute de Hristos. Căci nici nu a auzit pe Domnul, nici nu L-a urmat, ci mai târziu, după cum am spus, l-a urmat pe Petru, care își potrivea învățătura la nevoile ascultătorilor, dar fără intenția de a da o povestire închegată a cuvântărilor Domnului, așa încât Marcu nu a greșit scriind astfel unele lucruri după cum și le amintea. Căci a avut grijă de un singur lucru, să nu omită niciunul din lucrurile pe care le auzise și să nu spună vreunul în chip mincinos.” Aceste lucruri sunt povestite de Papias despre Marcu."},{"v":16,"t":"Dar despre Matei scrie astfel: „Așadar Matei a scris cuvintele în limba ebraică și fiecare le-a tălmăcit cum a putut.” Și același scriitor folosește mărturii din prima Epistolă a lui Ioan și din cea a lui Petru de asemenea. Și povestește o altă istorie despre o femeie care a fost învinuită de multe păcate înaintea Domnului, care este cuprinsă în Evanghelia după evrei. Aceste lucruri am socotit necesar să le observăm pe lângă ce s-a spus deja."}];
